  ('66dde3e0-95ed-4a7c-88cf-c10472f6a41f', 'adc8181a-08fc-46aa-b56f-480069abbb10', null, 'topic'::public.curated_course_node_type, 'Chemical Foundations, Measurement, Safety, and Scientific Practice', 'Chemistry starts with defensible measurement. This unit establishes the language, laboratory habits, uncertainty awareness, and safety judgment required across both semesters.', 0),
