  ('55dfe277-26fd-4913-bb5f-048eff56a65c', 'adc8181a-08fc-46aa-b56f-480069abbb10', null, 'topic'::public.curated_course_node_type, 'Chemical Measurement, Spectroscopy, and Data Quality', 'World-class chemistry requires more than calculations: students must know how evidence is generated, calibrated, checked, and communicated.', 16),
  ('62cd0082-a1c3-49da-9817-d96a6b1ca908', 'adc8181a-08fc-46aa-b56f-480069abbb10', '55dfe277-26fd-4913-bb5f-048eff56a65c', 'subtopic'::public.curated_course_node_type, 'Sampling, calibration, and analytical quality', 'A measurement is useful only when sampling, standards, uncertainty, and quality controls support the claim.', 0),
  ('248cb5c8-69fb-4063-9774-99cd48637ceb', 'adc8181a-08fc-46aa-b56f-480069abbb10', '62cd0082-a1c3-49da-9817-d96a6b1ca908', 'concept'::public.curated_course_node_type, 'Sampling plans, blanks, standards, spikes, and replicates', null, 0),
  ('9f775bf2-454e-468e-81de-d4b6a986a6c2', 'adc8181a-08fc-46aa-b56f-480069abbb10', '62cd0082-a1c3-49da-9817-d96a6b1ca908', 'concept'::public.curated_course_node_type, 'Calibration curves, linearity, residuals, and uncertainty', null, 1),
  ('242ca5d4-1ffd-460b-a84e-1cf83bba98b1', 'adc8181a-08fc-46aa-b56f-480069abbb10', '62cd0082-a1c3-49da-9817-d96a6b1ca908', 'concept'::public.curated_course_node_type, 'Accuracy, precision, sensitivity, detection limits, and method validation awareness', null, 2),
  ('24972fb9-c7e1-4dc8-ba9e-db2e847e05b8', 'adc8181a-08fc-46aa-b56f-480069abbb10', '55dfe277-26fd-4913-bb5f-048eff56a65c', 'subtopic'::public.curated_course_node_type, 'Spectroscopy and instrumental evidence', 'Interactions between matter and radiation can reveal identity, structure, and concentration.', 1),
  ('60d99586-9b10-4071-8fd8-f5c6eb7d84d7', 'adc8181a-08fc-46aa-b56f-480069abbb10', '24972fb9-c7e1-4dc8-ba9e-db2e847e05b8', 'concept'::public.curated_course_node_type, 'Beer-Lambert law and UV-visible spectroscopy', null, 0),
  ('81958e9a-329f-43a5-8e01-74038faf0500', 'adc8181a-08fc-46aa-b56f-480069abbb10', '24972fb9-c7e1-4dc8-ba9e-db2e847e05b8', 'concept'::public.curated_course_node_type, 'Atomic emission/absorption and fluorescence awareness', null, 1),
  ('ca4ada5f-3925-4601-bd0a-f3dc75a6eb1e', 'adc8181a-08fc-46aa-b56f-480069abbb10', '24972fb9-c7e1-4dc8-ba9e-db2e847e05b8', 'concept'::public.curated_course_node_type, 'Infrared vibrations, wavelength selection, baseline, and resolution', null, 2),
  ('b581b789-b8e9-4502-92fa-79ae138ebf63', 'adc8181a-08fc-46aa-b56f-480069abbb10', '55dfe277-26fd-4913-bb5f-048eff56a65c', 'subtopic'::public.curated_course_node_type, 'Separations, sensors, and reproducible analysis', 'Complex samples often require separation and transparent computational treatment before interpretation.', 2),
  ('f01d0774-2816-42bf-b5a5-7417092626f7', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'b581b789-b8e9-4502-92fa-79ae138ebf63', 'concept'::public.curated_course_node_type, 'Chromatography, stationary/mobile phases, retention, and resolution', null, 0),
  ('1318adde-e83a-4089-bbea-8e6d45deadf1', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'b581b789-b8e9-4502-92fa-79ae138ebf63', 'concept'::public.curated_course_node_type, 'Potentiometry, ion-selective electrodes, and biosensor calibration', null, 1),
  ('88b3fae8-d09d-4933-a5ff-9ec249226c56', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'b581b789-b8e9-4502-92fa-79ae138ebf63', 'concept'::public.curated_course_node_type, 'Spreadsheet or Python analysis, plots with units, metadata, versioning, and provenance', null, 2),
  ('e0541a30-3c9d-45b4-9c48-4566b8c6ae06', 'adc8181a-08fc-46aa-b56f-480069abbb10', null, 'topic'::public.curated_course_node_type, 'Sustainable Chemistry and Integrated Degree Applications', 'The sequence culminates in evidence-based decisions that connect chemistry to process design, ecosystems, food and human health while accounting for safety, uncertainty, ethics, and life-cycle effects.', 17),
  ('feb2ac90-a0da-4b04-9be3-708d4a7fe361', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'e0541a30-3c9d-45b4-9c48-4566b8c6ae06', 'subtopic'::public.curated_course_node_type, 'Chemical Engineering applications', 'Students use common chemistry to prepare for material and energy balances, transport, thermodynamics, and reaction engineering.', 0),
  ('27ffa4f0-a1f5-4337-9c59-c1db6050e2e9', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'feb2ac90-a0da-4b04-9be3-708d4a7fe361', 'concept'::public.curated_course_node_type, 'Process stoichiometry, recycle/purge awareness, and yield-selectivity tradeoffs', null, 0),
  ('e6135652-54be-408c-b7fc-c212564c48ae', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'feb2ac90-a0da-4b04-9be3-708d4a7fe361', 'concept'::public.curated_course_node_type, 'Phase, equilibrium, kinetic, and electrochemical constraints', null, 1),
  ('fd7f9819-df3b-4f9c-b03b-1ff213dfd0d1', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'feb2ac90-a0da-4b04-9be3-708d4a7fe361', 'concept'::public.curated_course_node_type, 'Reactor safety, corrosion, separations, energy intensity, and waste prevention', null, 2),
  ('19c69c39-7b40-4c0b-80e0-92e4d0f14850', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'e0541a30-3c9d-45b4-9c48-4566b8c6ae06', 'subtopic'::public.curated_course_node_type, 'Environmental Science applications', 'Chemical speciation and measurement explain contaminant behavior across air, water, soil, and treatment systems.', 1),
  ('63be7ad3-df30-49b0-ae56-d0ee9a6dc3fd', 'adc8181a-08fc-46aa-b56f-480069abbb10', '19c69c39-7b40-4c0b-80e0-92e4d0f14850', 'concept'::public.curated_course_node_type, 'Carbonate chemistry, redox, sorption, partitioning, and contaminant fate', null, 0),
  ('a935df35-561f-4fe2-a492-51e6d23bb1ac', 'adc8181a-08fc-46aa-b56f-480069abbb10', '19c69c39-7b40-4c0b-80e0-92e4d0f14850', 'concept'::public.curated_course_node_type, 'Atmospheric photochemistry, aerosols, greenhouse gases, and acid deposition awareness', null, 1),
  ('264dd593-4da1-4722-a419-d9bf9c6470ef', 'adc8181a-08fc-46aa-b56f-480069abbb10', '19c69c39-7b40-4c0b-80e0-92e4d0f14850', 'concept'::public.curated_course_node_type, 'Sampling, risk, remediation, green chemistry, and environmental justice', null, 2),
  ('83a63308-08ce-4ef1-b223-6a08b69c0afd', 'adc8181a-08fc-46aa-b56f-480069abbb10', 'e0541a30-3c9d-45b4-9c48-4566b8c6ae06', 'subtopic'::public.curated_course_node_type, 'Nutrition and Dietetics applications and capstone', 'Molecular interactions, equilibria, and measurement underpin food composition, nutrient function, digestion, and quality.', 2),
  ('9e68a33e-d3d5-4581-bf82-073f29a91025', 'adc8181a-08fc-46aa-b56f-480069abbb10', '83a63308-08ce-4ef1-b223-6a08b69c0afd', 'concept'::public.curated_course_node_type, 'Buffers, electrolytes, osmosis, minerals, and biochemical redox context', null, 0),
  ('f0cab301-f170-4845-8879-d451d52f6f60', 'adc8181a-08fc-46aa-b56f-480069abbb10', '83a63308-08ce-4ef1-b223-6a08b69c0afd', 'concept'::public.curated_course_node_type, 'Food energy, solubility, emulsions, oxidation, preservation, and nutrient analysis', null, 1),
