  ('adc8181a-08fc-46aa-b56f-480069abbb10', 'website'::public.curated_course_resource_kind, 'MIT 5.112 Principles of Chemical Science', 'https://ocw.mit.edu/courses/5-112-principles-of-chemical-science-fall-2005/', 'Honors-level electronic structure, thermodynamics, equilibria, kinetics, and catalysis.', 5),
  ('adc8181a-08fc-46aa-b56f-480069abbb10', 'website'::public.curated_course_resource_kind, 'ChemCollective', 'https://chemcollective.org/', 'Scenario-based problems and virtual laboratories for preparation and inquiry.', 6),
