  ('adc8181a-08fc-46aa-b56f-480069abbb10', 'website'::public.curated_course_resource_kind, 'Chemistry LibreTexts', 'https://chem.libretexts.org/Bookshelves/General_Chemistry', 'Supplemental explanations, examples, and alternative treatments.', 8),
