  ('adc8181a-08fc-46aa-b56f-480069abbb10', 'website'::public.curated_course_resource_kind, 'ACS Laboratory Safety for Chemistry Students', 'https://www.acs.org/education/policies/safety.html', 'RAMP, hazards, risk assessment, waste, operations, and emergency preparation.', 12),
